PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','moderator','admin')),password_salt TEXT,password_hash TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),deleted_at TEXT);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS subjects(id TEXT PRIMARY KEY,name TEXT NOT NULL,qualification TEXT NOT NULL,syllabus_code TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,UNIQUE(qualification,syllabus_code));
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,name TEXT NOT NULL,parent_topic_id TEXT REFERENCES topics(id) ON DELETE SET NULL,syllabus_version TEXT,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id),topic_id TEXT REFERENCES topics(id),qualification TEXT NOT NULL,syllabus_code TEXT NOT NULL,resource_type TEXT NOT NULL CHECK(resource_type IN ('past_paper','mark_scheme','examiner_report','topical','worksheet','notes')),exam_year INTEGER,session TEXT,paper_code TEXT,variant TEXT,title TEXT NOT NULL,source_url TEXT,r2_key TEXT,rights_status TEXT NOT NULL DEFAULT 'unverified' CHECK(rights_status IN ('unverified','authorized_link','licensed_file','open_license','rejected')),license_note TEXT,verified_by TEXT REFERENCES users(id),verified_at TEXT,checksum_sha256 TEXT,published INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT(datetime('now')),CHECK(published=0 OR rights_status IN ('authorized_link','licensed_file','open_license')));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,resource_id TEXT REFERENCES resources(id) ON DELETE SET NULL,topic_id TEXT REFERENCES topics(id) ON DELETE SET NULL,score REAL,max_score REAL,duration_seconds INTEGER,attempted_at TEXT NOT NULL DEFAULT(datetime('now')),notes TEXT);
CREATE TABLE IF NOT EXISTS saved_resources(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT(datetime('now')),PRIMARY KEY(user_id,resource_id));
CREATE TABLE IF NOT EXISTS worksheets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,subject_id TEXT NOT NULL REFERENCES subjects(id),topic_id TEXT REFERENCES topics(id),question_ids_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS discussions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,subject_id TEXT REFERENCES subjects(id),title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed','pending')),created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS replies(id TEXT PRIMARY KEY,discussion_id TEXT NOT NULL REFERENCES discussions(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed')),created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target_type TEXT NOT NULL CHECK(target_type IN ('discussion','reply','resource','user')),target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved','dismissed')),reviewed_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT,target_url TEXT,read_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_resources_subject_year ON resources(subject_id,exam_year);
CREATE INDEX IF NOT EXISTS idx_resources_rights ON resources(rights_status,published);
CREATE INDEX IF NOT EXISTS idx_attempts_user_date ON attempts(user_id,attempted_at);
CREATE INDEX IF NOT EXISTS idx_discussions_created ON discussions(status,created_at);
CREATE INDEX IF NOT EXISTS idx_replies_discussion ON replies(discussion_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read_at,created_at);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status,created_at);
